(r, big) => {
  if (big) {
    const k = r.int(0, 2), n = 100000;
    if (k === 0) return [r.str(n, "ABCXYZ")];
    if (k === 1) return [r.str(n, "abcxyz")];
    return ["Q" + r.str(n - 1, "abcxyz")];
  }
  return [r.bool(0.5) ? r.str(r.int(1, 6), "aAbB") : r.pick(["A", "a", "B"]) + r.str(r.int(0, 5), r.pick(["ab", "AB"]))];
}

