function capitalsUsedWell(word: string): boolean {
  let caps = 0;
  for (const ch of word) if (ch >= "A" && ch <= "Z") caps++;
  if (caps === 0 || caps === word.length) return true;
  return caps === 1 && word[0] >= "A" && word[0] <= "Z";
}

